```tsx
import React, { useState, useMemo, useCallback, memo } from 'react';

interface DataTableProps<T extends Record<string, unknown>> {
  data: T[];
  onRowClick: (row: T) => void;
  filters: Record<string, string>;
}

// Memoized table row component
const TableRow = memo(function TableRow<T extends Record<string, unknown>>({
  row,
  onClick,
  columns
}: {
  row: T;
  onClick: () => void;
  columns: string[];
}) {
  return (
    <tr onClick={onClick}>
      {columns.map((col) => (
        <td key={col}>{String(row[col])}</td>
      ))}
    </tr>
  );
});

export const DataTable = memo(function DataTable<T extends Record<string, unknown>>({
  data,
  onRowClick,
  filters
}: DataTableProps<T>) {
  const [sortColumn, setSortColumn] = useState<string>('name');
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');

  // Memoize column names
  const columns = useMemo(() => {
    return data.length > 0 ? Object.keys(data[0]) : [];
  }, [data]);

  // Memoize sorted data - only recalculate when dependencies change
  const sortedData = useMemo(() => {
    return [...data].sort((a, b) => {
      const aVal = a[sortColumn];
      const bVal = b[sortColumn];
      const comparison = String(aVal).localeCompare(String(bVal));
      return sortDirection === 'asc' ? comparison : -comparison;
    });
  }, [data, sortColumn, sortDirection]);

  // Memoize filtered data
  const filteredData = useMemo(() => {
    return sortedData.filter(row => {
      return Object.entries(filters).every(([key, value]) => {
        return String(row[key]).toLowerCase().includes(value.toLowerCase());
      });
    });
  }, [sortedData, filters]);

  // Memoize sort handler
  const handleSort = useCallback((column: string) => {
    setSortColumn(prev => {
      if (prev === column) {
        setSortDirection(d => d === 'asc' ? 'desc' : 'asc');
        return prev;
      }
      setSortDirection('asc');
      return column;
    });
  }, []);

  // Memoize row click handlers
  const handleRowClick = useCallback((row: T) => {
    onRowClick(row);
  }, [onRowClick]);

  return (
    <table>
      <thead>
        <tr>
          {columns.map(col => (
            <th
              key={col}
              onClick={() => handleSort(col)}
              style={{ cursor: 'pointer' }}
            >
              {col}
              {sortColumn === col && (sortDirection === 'asc' ? ' ↑' : ' ↓')}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {filteredData.map((row, idx) => (
          <TableRow
            key={row.id ?? idx}
            row={row}
            onClick={() => handleRowClick(row)}
            columns={columns}
          />
        ))}
      </tbody>
    </table>
  );
});
```

## Key Optimizations:

1. **`useMemo` for expensive computations** - Sorting and filtering only run when their dependencies change

2. **`useCallback` for event handlers** - Prevents creating new function references on every render

3. **`memo` for component memoization** - Both `DataTable` and `TableRow` are memoized

4. **Removed unnecessary `useEffect`** - The sorting logic is now handled with `useMemo` instead

5. **Stable keys** - Using `row.id` when available instead of array index

6. **Extracted `TableRow` component** - Allows individual rows to skip re-renders
